$q=trim((string)getv('q',''));$scope=trim((string)getv('scope','all'));$match=trim((string)getv('match','contains'));$uid=(int)current_user()['id'];$isAdmin=(current_user()['role']??'')==='admin';
$allowedScopes=['all','tasks','notes','projects','code','files','links','support','documentation','settings'];if($isAdmin)$allowedScopes=array_merge($allowedScopes,['users','pages']);if(!in_array($scope,$allowedScopes,true))$scope='all';if(!in_array($match,['contains','exact'],true))$match='contains';
$results=['tasks'=>[],'notes'=>[],'projects'=>[],'code'=>[],'files'=>[],'links'=>[],'support'=>[],'documentation'=>[],'settings'=>[],'users'=>[],'pages'=>[]];
$like=$match==='exact'?$q:'%'.$q.'%';
function search_mark(string $text,string $q):string{$safe=e($text);if($q==='')return $safe;return preg_replace('/('.preg_quote(e($q),'/').')/iu','<mark class="search-match">$1</mark>',$safe)??$safe;}
function search_static_match(string $q,array $aliases):bool{if($q==='')return false;foreach($aliases as $a)if(stripos($a,$q)!==false)return true;return false;}
if($q!==''){
 $queries=[
 'tasks'=>"SELECT id,title,description,updated_at FROM tasks WHERE user_id=? AND (title LIKE ? OR description LIKE ?) ORDER BY updated_at DESC LIMIT 30",
 'notes'=>"SELECT id,title,content,updated_at FROM notes WHERE user_id=? AND (title LIKE ? OR content LIKE ?) ORDER BY updated_at DESC LIMIT 30",
 'projects'=>"SELECT id,name AS title,description,updated_at FROM projects WHERE user_id=? AND (name LIKE ? OR description LIKE ?) ORDER BY updated_at DESC LIMIT 30",
 'code'=>"SELECT id,title,language,category,tags_json,updated_at FROM code_snippets WHERE user_id=? AND status<>'deleted' AND (title LIKE ? OR category LIKE ? OR tags_json LIKE ? OR code_text LIKE ?) ORDER BY updated_at DESC LIMIT 30",
 'files'=>"SELECT id,original_name,mime_type,size_bytes,created_at FROM file_objects WHERE user_id=? AND status NOT IN ('deleted','quarantined') AND (original_name LIKE ? OR mime_type LIKE ?) ORDER BY created_at DESC LIMIT 30",
 'links'=>"SELECT id,slug,title,destination_url,updated_at FROM short_links WHERE user_id=? AND (slug LIKE ? OR title LIKE ? OR destination_url LIKE ?) ORDER BY updated_at DESC LIMIT 30",
 'support'=>"SELECT sm.id,sm.body,sm.created_at,st.id AS thread_id FROM support_messages sm INNER JOIN support_threads st ON st.id=sm.thread_id WHERE st.user_id=? AND sm.body LIKE ? ORDER BY sm.created_at DESC LIMIT 30"];
 foreach($queries as $k=>$sql){if($scope!=='all'&&$scope!==$k)continue;try{$s=db()->prepare($sql);if(in_array($k,['tasks','notes','projects'],true))$s->execute([$uid,$like,$like]);elseif($k==='code')$s->execute([$uid,$like,$like,$like,$like]);elseif($k==='files')$s->execute([$uid,$like,$like]);elseif($k==='links')$s->execute([$uid,$like,$like,$like]);else$s->execute([$uid,$like]);$results[$k]=$s->fetchAll();}catch(Throwable $e){$results[$k]=[];}}
 try{$s=db()->prepare("SELECT id,slug,title,summary,section FROM documentation_entries WHERE visibility IN ('private','shared') AND (title LIKE ? OR summary LIKE ? OR section LIKE ? OR overview LIKE ? OR requirements LIKE ? OR steps_json LIKE ? OR troubleshooting_json LIKE ?) ORDER BY section,title LIMIT 40");$s->execute([$like,$like,$like,$like,$like,$like,$like]);$results['documentation']=$s->fetchAll();}catch(Throwable $e){}
 if($isAdmin&&($scope==='all'||$scope==='pages')){
  try{$s=db()->prepare("SELECT page_slug,title FROM site_content WHERE page_slug LIKE ? OR title LIKE ? OR html_content LIKE ? ORDER BY page_slug LIMIT 30");$s->execute([$like,$like,$like]);$results['pages']=$s->fetchAll();}catch(Throwable $e){}
  if($scope==='all'||$scope==='users')try{$s=db()->prepare("SELECT id,full_name,email,username,role,plan,status FROM users WHERE full_name LIKE ? OR email LIKE ? OR username LIKE ? OR role LIKE ? OR plan LIKE ? OR status LIKE ? ORDER BY id DESC LIMIT 50");$s->execute([$like,$like,$like,$like,$like,$like]);$results['users']=$s->fetchAll();}catch(Throwable $e){}
 }
 $settings=[
 ['My Settings','/settings/',['my settings','settings','preferences','account settings']],['File Storage & Sharing','/files/',['file','files','file storage','sharing','upload']],['Developer API','/settings/link-api/',['developer api','api','link api']],['AWS Bedrock','/settings/ai/',['aws bedrock','bedrock','aws','ai']],['Plans & Billing','/billing/',['plans','billing','payment','subscription']],['Support Chat','/support/',['support','support chat','help desk','admin support']],['Help & Documentation','/docs/',['help','documentation','docs','help center','guide','guides']],['Links & Analytics','/links/',['links','link analytics','analytics','short link']],['Code Editor','/code/',['code','code editor','live code editor','editor']],['AI Assistant','/ai/',['ai assistant','assistant','ai chat']]];
 if($isAdmin){$settings=array_merge($settings,[['Website Name','/admin/settings/?focus=website-name',['website name','site name']],['Website URL','/admin/settings/?focus=website-url',['website url','site url','domain']],['Live Site Editor','/admin/site-editor/?focus=site-editor',['live site editor','site editor','visual editor']],['Theme and colors','/admin/site-editor/?focus=theme-settings',['theme','colors','appearance']],['Live Platform Activity counters','/admin/platform-activity/?focus=latest-month',['platform activity','counters','activity']],['Auto-Fill counters','/admin/platform-activity/?focus=autofill-registered_users_display',['autofill','registered users','counters']],['AWS Bedrock API','/admin/ai/?focus=bedrock-api',['bedrock api','aws api','api key']],['AWS Region','/admin/ai/?focus=bedrock-region',['aws region','bedrock region','region']],['Model','/admin/ai/?focus=bedrock-model',['model','model id']],['Relay URL','/admin/ai/?focus=relay-url',['relay','relay url']],['Users','/admin/users/',['users','user management','accounts']],['Create User','/admin/user-create/',['create user','new user','add user']],['Documentation CMS','/admin/docs/',['documentation cms','docs cms','manage documentation']],['Admin Support Chat','/admin/support/',['admin support','support management']],['Billing Requests','/admin/billing/',['billing requests','subscription requests']]]);}
 if($scope==='all'||$scope==='settings')foreach($settings as $item)if(search_static_match($q,$item[2]))$results['settings'][]=['label'=>$item[0],'url'=>$item[1]];
}
