elseif($group==='code'):foreach($items as $x):?><a class="search-result" href="/code/?id=<?=e((string)$x['id'])?>&highlight=<?=rawurlencode($q)?>"><span class="search-result-main"><strong><?=search_mark($x['title'],$q)?></strong><small><?=search_mark(($x['language']??'text').' · '.($x['category']??'No category'),$q)?></small></span><span class="search-result-type">Open code</span></a><?php endforeach;
elseif($group==='files'):foreach($items as $x):$name=$x['original_name']??$x['label']??'File';$sub=$x['mime_type']??$x['subtitle']??'Media';$url=$x['url']??'/media/';if(strpos($url,'highlight=')===false)$url.=(strpos($url,'?')===false?'?':'&').'highlight='.rawurlencode($q);?><a class="search-result" href="<?=e($url)?>"><span class="search-result-main"><strong><?=search_mark($name,$q)?></strong><small><?=search_mark($sub,$q)?></small></span><span class="search-result-type">Open</span></a><?php endforeach;
elseif($group==='links'):foreach($items as $x):?><a class="search-result" href="/links/?focus=link-<?=e((string)$x['id'])?>&highlight=<?=rawurlencode($q)?>#link-<?=e((string)$x['id'])?>"><span class="search-result-main"><strong><?=search_mark($x['title']?:$x['slug'],$q)?></strong><small><?=search_mark($x['slug'].' · '.$x['destination_url'],$q)?></small></span><span class="search-result-type">Link</span></a><?php endforeach;
