elseif($group==='documentation'):foreach($items as $x):?><a class="search-result" href="/docs/?highlight=<?=rawurlencode($q)?>#<?=e($x['slug'])?>"><span class="search-result-main"><strong><?=search_mark($x['title'],$q)?></strong><small><?=search_mark($x['section'].' · '.$x['summary'],$q)?></small></span><span class="search-result-type">Guide</span></a><?php endforeach;
elseif($group==='settings'):foreach($items as $x):?><a class="search-result" href="<?=e(strpos($x['url'],'highlight=')===false?$x['url'].(strpos($x['url'],'?')===false?'?':'&').'highlight='.rawurlencode($q):$x['url'])?>"><span class="search-result-main"><strong><?=search_mark($x['label'],$q)?></strong><small>Open and focus</small></span><span class="search-result-type">Setting</span></a><?php endforeach;
